function npcPaint(o,{g,p},base=0){const q=p(o.x+o.w/2,o.y+o.h/2,base),im=images[o.sprite];g.save();g.fillStyle='#472b3228';g.beginPath();g.ellipse(q.x,q.y,10,3,0,0,Math.PI*2);g.fill();if(im?.complete&&im.naturalWidth){g.imageSmoothingEnabled=false;const cell=im.naturalHeight/4;g.drawImage(im,(im.naturalWidth-cell)/2,0,cell,cell,q.x-23,q.y-44.56,46,46);}g.font='600 10px "Malgun Gothic",sans-serif';g.textAlign='center';g.fillStyle='#fff7e6';const w=g.measureText(o.name).width+12;g.fillRect(q.x-w/2,q.y-62,w,16);g.fillStyle='#56363e';g.fillText(o.name,q.x,q.y-50);g.restore();return true;}
