if(o.type==='mission-workstation'){
 box(o.x,o.y,o.w,o.h,z,24,'#d6b88c','#9a735d','#6a4f48');box(o.x+3,o.y+3,o.w-6,o.h-6,z+24,4,'#f6e6c9','#c8aa82','#907568');
 const q=p(o.x+o.w/2,o.y+8,z+56);g.fillStyle='#533e46';g.fillRect(q.x-26,q.y,52,30);g.fillStyle='#bad5d0';g.fillRect(q.x-23,q.y+3,46,24);g.fillStyle='#4f7777';g.font='700 9px monospace';g.textAlign='left';g.fillText('SELECT ...',q.x-20,q.y+13);g.fillText('FROM (...)',q.x-20,q.y+23);box(o.x+12,o.y+o.h-10,o.w-24,8,z+28,2,'#657d7e','#485e63','#394b53');return true;
}
if(o.type==='mission-cabinet'){box(o.x,o.y,o.w,o.h,z,52,'#f1d9af','#b08a6b','#775746');for(let i=0;i<5;i++){const x=o.x+8+i*(o.w-16)/5;box(x,o.y+o.h+1,(o.w-28)/5,2,z+4,39,'#caad8c','#d3b795','#8a6d56');}box(o.x-2,o.y-2,o.w+4,o.h+3,z+52,4,'#fff0d0','#b99475','#725649');for(let i=0;i<Math.floor((o.w-15)/18);i++)box(o.x+8+i*18,o.y+8,11,13,z+56,10,i%2?'#d8acb7':'#84655a','#a7757b','#795352');return true;}
if(o.type==='mission-sign'){const q=p(o.x+o.w/2,o.y,z+75);g.fillStyle='#69454c';g.fillRect(q.x-o.w/2,q.y-21,o.w,30);g.strokeStyle='#d8b979';g.strokeRect(q.x-o.w/2+3,q.y-18,o.w-6,24);g.font='700 13px Georgia';g.textAlign='center';g.fillStyle='#ffe7b2';g.fillText(o.text,q.x,q.y-1,o.w-14);return true;}
if(o.type==='mission-plant'){box(o.x,o.y,o.w,o.h,z,16,'#ead8b8','#b8957c','#735647');for(let i=0;i<5;i++){const q=p(o.x+o.w/2+Math.sin(i*2)*8,o.y+o.h/2+Math.cos(i*2)*6,z+22+i%2*7);g.fillStyle=i%2?'#65836e':'#49685a';g.beginPath();g.ellipse(q.x,q.y,8,13,i,0,Math.PI*2);g.fill();}return true;}
if(o.type==='mission-evidence-board'){for(const x of [o.x+8,o.x+o.w-12])box(x,o.y+o.h-3,4,4,z,40,'#b89a72','#8f7359','#635244');const q=p(o.x+o.w/2,o.y+o.h,z+55),w=o.w;g.fillStyle='#694e40';g.beginPath();g.roundRect(q.x-w/2-3,q.y-42,w+6,53,3);g.fill();g.fillStyle='#b99872';g.fillRect(q.x-w/2,q.y-39,w,47);g.strokeStyle='#96515e';g.lineWidth=1;g.beginPath();g.moveTo(q.x-26,q.y-25);g.lineTo(q.x+27,q.y-12);g.lineTo(q.x,q.y-30);g.stroke();for(let i=0;i<3;i++){const x=q.x-w/2+6+i*(w-12)/3,y=q.y-32+i%2*9;g.fillStyle='#fff1d2';g.fillRect(x,y,19,27);g.fillStyle='#a65f65';g.beginPath();g.arc(x+9,y+3,2,0,Math.PI*2);g.fill();g.fillStyle='#b39b7c';for(let k=0;k<3;k++)g.fillRect(x+3,y+9+k*5,12,1);}return true;}
if(o.type==='mission-files'){box(o.x,o.y,o.w,o.h,z,27,'#c4ac8d','#8b7563','#665849');for(let i=0;i<5;i++)box(o.x+5+i*10,o.y+5,8,28,z+27,18,i%2?'#ab8690':'#d6c09b','#ab8e78','#775b55');return true;}
if(o.type==='mission-bench'){box(o.x,o.y,o.w,o.h,z,19,'#ac788a','#88556d','#684356');box(o.x,o.y,o.w,7,z+19,22,'#c799a5','#ac7d8c','#85596e');return true;}
